def fetch(lokal, remote):
    baru = sorted(i for i in remote['commits'] if i not in lokal['commits'])
    for i in baru:
        lokal['commits'][i] = remote['commits'][i]
    for nama, tip in remote['cabang'].items():
        lokal['cabang']['origin/' + nama] = tip
    return baru

