        hasil = set()
        sekarang = ident
        while sekarang is not None:
            hasil.add(sekarang)
            sekarang = commits[sekarang]['parent']
        return hasil
    sa, sb = telusur(a), telusur(b)
    return (len(sa - sb), len(sb - sa))

